def compute_a(n_max):
    a = [0] * (n_max + 1)
    a[1] = 0
    for n in range(2, n_max + 1):
        max_val = -float('inf')
        for i in range(1, n):
            val = a[i] + a[n-i] + min(i, n-i)
            if val > max_val:
                max_val = val
        a[n] = max_val
