def compute_a(n_max):
    a = [0] * (n_max + 1)
    a[1] = 0
    for n in range(2, n_max + 1):
        max_val = -float('inf')
        for i in range(1, n // 2 + 1):
            val = a[i] + a[n-i] + i
            if val > max_val:
                max_val = val
        a[n] = max_val
    return a

a_vals = compute_a(2025)
print(f"a(2025) = {a_vals[2025]}")
